script:
(function () {
  'use strict';
  // One timeline: save for S years, then withdraw for W years.
  // Saving: contributions at the END of each period (f per year), period rate
  // qs = (1 + saving return)^(1/f) - 1; the amount can rise once a year with inflation.
  // Withdrawing: withdrawals at the START of each period (fw per year), period rate
  // qw = (1 + withdrawal return)^(1/fw) - 1; the amount can rise once a year with inflation i.
  // Sustainable first-year withdrawal that leaves $0 after W years:
  //   w = B / sum over years j < W of (1 + i)^j x sum over p < fw of (1 + qw)^-(j x fw + p)
  // Chosen-amount mode runs the same schedule and stops when the balance runs out.
  // CHECKS (Node, scratch tests/sd.test.js): $10,000 + $500/month for 20 years at 7%/yr effective
  // equals the closed form 10,000 x 1.07^20 + 500 x ((1 + q)^240 - 1) / q, q = 1.07^(1/12) - 1
  // = $38,696.84 + $253,768.19 = $292,465.03; $300,000 withdrawn monthly at
  // the start of each month for 25 years at 0% with no raises = $1,000 a month; at 5% with no raises
  // the payment equals the annuity-due formula B x q / ((1 - (1 + q)^-300) x (1 + q)) = $1,727.38; the
  // period-by-period run with the solved withdrawal ends at $0.00 (with and without inflation
  // raises); a withdrawal larger than the sustainable one runs out early and reports the age.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var FREQ_WORD = { 12: 'month', 4: 'quarter', 1: 'year' };
  var IDS = ['sdMain', 'sdPeak', 'sdIn', 'sdOut', 'sdToday', 'sdAges', 'sdGrowth', 'sdEnd'];

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function periodRate(r, f) { return Math.pow(1 + r, 1 / f) - 1; }

  function sustainable(B, rw, fw, W, i) {
    var q = periodRate(rw, fw), s = 0;
    for (var j = 0; j < W; j++) {
      for (var p = 0; p < fw; p++) s += Math.pow(1 + i, j) * Math.pow(1 + q, -(j * fw + p));
    }
    return s > 0 ? B / s : 0;
  }

  // o: start, contrib, cf, S, rs, raiseC, W, rw, fw, raiseW, i, mode ('max' | 'fixed'), amount
  function run(o) {
    var rows = [], bal = o.start, qs = periodRate(o.rs, o.cf), qw = periodRate(o.rw, o.fw), totalIn = o.start, totalOut = 0;
    for (var y = 0; y < o.S; y++) {
      var c = o.contrib * (o.raiseC ? Math.pow(1 + o.i, y) : 1), open = bal, added = 0;
      for (var p = 0; p < o.cf; p++) { bal = bal * (1 + qs) + c; added += c; }
      totalIn += added;
      rows.push({ year: y + 1, phase: 'Saving', added: added, out: 0, growth: bal - open - added, balance: bal });
    }
    var peak = bal;
    var w = o.mode === 'max' ? sustainable(peak, o.rw, o.fw, o.W, o.raiseW ? o.i : 0) : o.amount, runsOut = null;
    for (var j = 0; j < o.W; j++) {
      var amt = w * (o.raiseW ? Math.pow(1 + o.i, j) : 1), open2 = bal, out = 0;
      for (var k = 0; k < o.fw; k++) {
        var take = Math.min(amt, bal);
        if (runsOut === null && o.mode === 'fixed' && amt > 0 && bal - amt < -0.005) runsOut = o.S + j + k / o.fw;
        bal = (bal - take) * (1 + qw);
        out += take;
      }
      if (bal < 0.005) bal = 0;
      totalOut += out;
      rows.push({ year: o.S + j + 1, phase: 'Withdrawing', added: 0, out: out, growth: bal - open2 + out, balance: bal });
    }
    return { rows: rows, peak: peak, w: w, totalIn: totalIn, totalOut: totalOut, end: bal, runsOut: runsOut };
  }

  function update() {
    var mode = document.getElementById('sdMode').value;
    document.getElementById('sdWrapAmount').hidden = mode !== 'fixed';
    var o = {
      start: num('sdStart'), contrib: num('sdContrib'), cf: parseInt(document.getElementById('sdContribFreq').value, 10),
      S: Math.round(num('sdSaveYears')), rs: num('sdSaveRate'), W: Math.round(num('sdDrawYears')), rw: num('sdDrawRate'),
      fw: parseInt(document.getElementById('sdDrawFreq').value, 10), amount: num('sdAmount'), i: num('sdInflation'),
      raiseC: document.getElementById('sdRaiseContrib').value === 'yes', raiseW: document.getElementById('sdRaiseDraw').value === 'yes', mode: mode
    };
    var age = Math.round(num('sdAge'));
    var error = document.getElementById('sdError'), msg = '';
    if ([o.start, o.contrib].some(isNaN) || o.start < 0 || o.contrib < 0) msg = 'Enter a starting balance and contribution of $0 or more.';
    else if (isNaN(age) || age < 0 || age > 100) msg = 'Enter a current age from 0 to 100.';
    else if (isNaN(o.S) || o.S < 0 || o.S > 70 || isNaN(o.W) || o.W < 1 || o.W > 70) msg = 'Enter 0 to 70 years of saving and 1 to 70 years of withdrawals.';
    else if ([o.rs, o.rw].some(isNaN) || o.rs < -50 || o.rs > 50 || o.rw < -50 || o.rw > 50) msg = 'Enter annual returns from -50% to 50%.';
    else if (isNaN(o.i) || o.i < -10 || o.i > 30) msg = 'Enter an inflation rate from -10% to 30%.';
    else if (mode === 'fixed' && (isNaN(o.amount) || o.amount < 0)) msg = 'Enter a withdrawal amount of $0 or more.';
    error.hidden = !msg;
    if (msg) {
      error.textContent = msg;
      IDS.forEach(function (id) { set(id, '–'); });
      set('sdSummary', '');
      document.getElementById('sdSchedule').innerHTML = '';
      return;
    }
    o.rs /= 100; o.rw /= 100; o.i /= 100;
    var r = run(o), word = FREQ_WORD[o.fw] || 'period';
    var drawAge = age + o.S, endAge = drawAge + o.W;
    if (mode === 'max') {
      set('sdMainLabel', 'You can withdraw each ' + word);
      set('sdMain', money.format(r.w));
      set('sdSummary', 'Saving for ' + o.S + (o.S === 1 ? ' year' : ' years') + ' builds ' + money.format(r.peak) +
          ', which can pay ' + money.format(r.w) + ' at the start of each ' + word + (o.raiseW ? ' (rising with inflation each year)' : '') +
          ' for ' + o.W + (o.W === 1 ? ' year' : ' years') + ', from age ' + drawAge + ' to ' + endAge + '.');
    } else if (r.runsOut !== null) {
      set('sdMainLabel', 'Money runs out at age');
      set('sdMain', String(Math.floor(age + r.runsOut)));
      set('sdSummary', 'At ' + money.format(o.amount) + ' each ' + word + ', the account runs dry about ' +
          (r.runsOut - o.S).toFixed(1) + ' years into withdrawals, before the ' + o.W + '-year plan ends. The most it can pay for the full period is ' +
          money.format(sustainable(r.peak, o.rw, o.fw, o.W, o.raiseW ? o.i : 0)) + ' each ' + word + '.');
    } else {
      set('sdMainLabel', 'Balance left at age ' + endAge);
      set('sdMain', money.format(r.end));
      set('sdSummary', 'At ' + money.format(o.amount) + ' each ' + word + ', the account lasts the full ' + o.W +
          (o.W === 1 ? ' year' : ' years') + ' and still holds ' + money.format(r.end) + ' at age ' + endAge + '.');
    }
    set('sdPeak', money.format(r.peak));
    set('sdIn', money.format(r.totalIn));
    set('sdOut', money.format(r.totalOut));
    set('sdToday', money.format(r.w / Math.pow(1 + o.i, o.S)));
    set('sdAges', drawAge + ' to ' + endAge);
    set('sdGrowth', (r.end + r.totalOut - r.totalIn < 0 ? '−' : '') + money.format(Math.abs(r.end + r.totalOut - r.totalIn)));
    set('sdEnd', money.format(r.end));
    document.getElementById('sdSchedule').innerHTML = r.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + (age + row.year) + '</td><td>' + row.phase + '</td><td>' + money.format(row.added) +
             '</td><td>' + money.format(row.out) + '</td><td>' + (row.growth < -0.005 ? '−' : '') + money.format(Math.abs(row.growth)) +
             '</td><td>' + money.format(row.balance) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('sdForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
